const completeFamilyLayoutBase=familyLayout;
familyLayout=function(w=world){const originalRoot=familyRoot,originalSearch=familySearch;familySearch='';let allowed=null;if(originalRoot&&studioFamilyDirection!=='connected'){
 allowed=new Set([originalRoot]);const queue=[originalRoot],links=familyVisibleLinks(w).filter(r=>['parent','adoptive','successor'].includes(r.role));while(queue.length){const id=queue.shift();for(const r of links){const next=studioFamilyDirection==='ancestors'&&r.to===id?r.from:studioFamilyDirection==='descendants'&&r.from===id?r.to:null;if(next&&!allowed.has(next)){allowed.add(next);queue.push(next);}}}familyRoot='';}
 let result;try{result=completeFamilyLayoutBase(w);}finally{familyRoot=originalRoot;familySearch=originalSearch;}
 if(allowed){familyRoot='';familySearch='';try{result=completeFamilyLayoutBase({...w,entries:w.entries.filter(e=>allowed.has(e.id)),familyLinks:w.familyLinks.filter(r=>allowed.has(r.from)&&allowed.has(r.to))});}finally{familyRoot=originalRoot;familySearch=originalSearch;}}
 return result;};
const completeFamilySVGBase=familySVG;familySVG=function(w=world){let art=completeFamilySVGBase(w);const styles=getComputedStyle(document.body),colour=k=>styles.getPropertyValue(k).trim()||'#243834';const replacements={'#20242c':colour('--panel'),'#343f49':colour('--soft'),'#f3eee3':colour('--ink'),'#b8c8ca':colour('--muted'),'#9dc7bb':colour('--green'),'#ddbb73':colour('--accent'),'#c7a6db':colour('--accent')};for(const [a,b]of Object.entries(replacements))art=art.split(a).join(b);
 for(const e of familyLayout(w).items){const marker=`data-family-person="${e.id}"`;art=art.replace(marker,marker+' class="studio-family-person"');const old=`${esc(e.born??'')} ${e.died!=null?'– '+esc(e.died):''}`,dates=[e.birthYear!=null?'Born '+e.birthYear:'',e.deathYear!=null?'d. '+e.deathYear:''].filter(Boolean).join(' · ');if(dates){const start=art.indexOf(marker),end=art.indexOf('</g>',start),part=art.slice(start,end).replace(`font-size="10">${old}</text>`,`font-size="10">${esc(dates)}</text>`);art=art.slice(0,start)+part+art.slice(end);}if(familySearch&&!e.name.toLowerCase().includes(familySearch.toLowerCase())){const start=art.indexOf(marker);art=art.slice(0,start)+art.slice(start).replace('class="studio-family-person"','class="studio-family-person" opacity=".35"');}}
 return art;};
const completeFamilyPageBase=familyPage;familyPage=function(){return completeFamilyPageBase().replace('<div style="overflow:auto;max-height:65vh">',`<div class="row">${field('Show',`<select id="studioFamilyDirection"><option value="connected" ${studioFamilyDirection==='connected'?'selected':''}>Whole connected family</option><option value="ancestors" ${studioFamilyDirection==='ancestors'?'selected':''}>Ancestors / predecessors</option><option value="descendants" ${studioFamilyDirection==='descendants'?'selected':''}>Descendants / successors</option></select>`)}${btn(studioFamilyFit?'Actual size':'Fit to width','studio-family-fit')}<small>Search highlights people while keeping their connections visible.</small></div><div class="studio-family-canvas" ${studioFamilyFit?'style="--family-fit:1"':''}>`).replace('width="'+familyLayout().width+'" height="'+familyLayout().height+'" role="img"',`width="${studioFamilyFit?'100%':familyLayout().width}" height="${studioFamilyFit?'auto':familyLayout().height}" role="img"`);};
document.addEventListener('change',e=>{if(e.target.id==='studioFamilyDirection'){studioFamilyDirection=e.target.value;render();}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b?.dataset.action==='studio-family-fit'){studioFamilyFit=!studioFamilyFit;render();}if(b?.dataset.action==='family-remove'){e.preventDefault();e.stopImmediatePropagation();const id=b.dataset.id;confirmDelete('Remove this family relationship?',()=>world.familyLinks=world.familyLinks.filter(r=>r.id!==id));}},true);
