worldKitWorkspace=function(){return pageHead('World kit','Create, customise and reuse the look and sound of your world.',btn('＋ Create kit','kc-create','','accent')+btn('Import / manage kits','workshop-kits'))+`<section class="card"><h2>Your visual kits</h2><p>A kit combines artwork, textures, colours, lettering and atmosphere. Editing a saved kit leaves applied maps unchanged until you apply it again.</p><div class="studio-catalog-grid">${world.worldKits.map(k=>`<article class="mini-card studio-kit-card"><div class="studio-kit-preview">${kitSample(k)}</div><h2>${esc(k.name)}</h2><small>${world.defaultKitId===k.id?'Default for new maps · ':''}${esc(MAP_PACKS[k.mapStyle]?.name||k.mapStyle)} · ${esc(CARTO_STYLES[k.cartographyStyle]?.name||k.cartographyStyle)}</small><div class="actions">${btn('Edit','kc-edit',`data-id="${k.id}"`)}${btn('Apply…','studio-kit-apply',`data-id="${k.id}"`)}${btn('Duplicate','kc-duplicate',`data-id="${k.id}"`)}${btn('Export','workshop-kit-export',`data-id="${k.id}"`)}</div></article>`).join('')||empty('Create your first kit from a studio look, or capture a map you already love.')}</div><div class="actions">${btn('Capture current map','workshop-kit-capture')}${btn('Browse studio kits','builtin-kits')}</div></section><div class="workshop-map-cards"><section class="card"><h2>Artwork & surfaces</h2><p>Browse built-in symbols or your imported artwork. Replace media everywhere through Media health, or change individual slots inside a kit.</p>${btn('Browse assets','navigate','data-view="assets"')}${btn('Import artwork','import-assets')}${btn('Media health / replacement','studio-media-health')}</section><section class="card"><h2>Names & cultures</h2><p>Generate people and places, edit naming cultures and keep favourites.</p>${btn('Naming workshop','workshop-names')}<p>${world.nameFavourites.length} saved favourites</p></section><section class="card"><h2>Flags & emblems</h2><p>Create, revisit and export designs for places, families and factions.</p>${btn('Flags & emblems','workshop-emblems')}<p>${world.emblems.length} saved designs</p></section><section class="card"><h2>Sound & music</h2><p>Import tracks, hear starter sounds, organise playlists and attach audio to places.</p>${btn('Sound desk','workshop-sound')}</section></div><section class="card"><h2>Develop & share</h2><div class="actions">${btn('Guided world entry','workshop-guide')}${btn('Compare entries','workshop-compare')}${btn('World consistency review','workshop-review')}${btn('Story chronicle','workshop-share-timeline')}${btn('Connection atlas','workshop-share-connections')}${btn('Building floor atlas','workshop-floor-atlas')}</div>${btn('All export options','export')}</section>`;};
const completeCreateKitBase=createWorldKit;createWorldKit=function(id=''){if(currentMap()||world.maps.length)return completeCreateKitBase(id);const saved=world.worldKits.find(k=>k.id===id);kitDraft=saved?clone(saved):captureWorldKit(makeMap('Kit sample','parchment'),'My world kit');kitDraftOriginal=saved?.id||'';kitDraftTab='style';if(!saved)styleKitDraft(kitDraft,'parchment');showKitCreator();};
let studioAssetSource='all',studioAssetCategory='all',studioAssetStyle='fantasy',studioAssetVariant=0,studioAssetQuery='',studioAssetPage=0;
function studioAssetResults(){const q=studioAssetQuery.toLowerCase(),builtin=Object.entries(SYMBOLS).filter(([id,s])=>(studioAssetCategory==='all'||(MAP_ASSET_CATEGORIES[studioAssetCategory]||[]).includes(id))&&(!q||(s.name+' '+id).toLowerCase().includes(q))).map(([id,s])=>({id,name:s.name,builtin:true})),imported=world.assets.filter(a=>!q||a.name.toLowerCase().includes(q));return studioAssetSource==='built-in'?builtin:studioAssetSource==='imported'?imported:[...imported,...builtin];}
function studioAssetGrid(){const items=studioAssetResults(),pageSize=40,last=Math.max(0,Math.ceil(items.length/pageSize)-1);studioAssetPage=Math.min(studioAssetPage,last);return `<p>${items.length} ${items.length===1?'asset':'assets'} · page ${studioAssetPage+1} of ${last+1}</p><div class="studio-catalog-grid">${items.slice(studioAssetPage*pageSize,(studioAssetPage+1)*pageSize).map(a=>`<article class="card studio-catalog-item">${a.builtin?builtInAssetSVG(a.id,studioAssetStyle,studioAssetVariant):`<img loading="lazy" src="${esc(a.src)}" alt="${esc(a.name)}">`}<h3>${esc(a.name)}</h3><small>${a.builtin?esc(MAP_PACKS[studioAssetStyle]?.name||studioAssetStyle)+' · variation '+(studioAssetVariant+1):'Imported · '+a.width+' × '+a.height}</small><div class="actions">${a.builtin?btn('Place','studio-asset-place',`data-symbol="${a.id}"`)+btn('Export SVG','studio-asset-svg',`data-symbol="${a.id}"`):btn('Place','place-asset',`data-id="${a.id}"`)+btn('Attach','x-asset-attach',`data-id="${a.id}"`)+btn('Remove','delete-asset',`data-id="${a.id}"`,'danger')}</div></article>`).join('')||empty('No assets match. Try another category or search.')}</div><div class="row">${studioAssetPage>0?btn('← Previous','studio-assets-page','data-step="-1"'):''}${studioAssetPage<last?btn('Next →','studio-assets-page','data-step="1"'):''}</div>`;}
renderAssets=function(){return pageHead('Assets','Built-in artwork and your own imported images, in one searchable space.',btn('Import artwork','import-assets','','accent')+btn('Import studio transfer / loop','x-suite-import')+btn('World kit','navigate','data-view="worldkit"'))+`<section class="card"><div class="fields">${field('Show',`<select id="studioAssetSource"><option value="all" ${studioAssetSource==='all'?'selected':''}>All assets</option><option value="built-in" ${studioAssetSource==='built-in'?'selected':''}>Built-in artwork</option><option value="imported" ${studioAssetSource==='imported'?'selected':''}>Imported artwork</option></select>`)}${field('Find artwork',`<input id="studioAssetQuery" type="search" value="${esc(studioAssetQuery)}" placeholder="Rock, firepit, airship…">`)}${field('Built-in category',`<select id="studioAssetCategory"><option value="all">All categories</option>${options(Object.keys(MAP_ASSET_CATEGORIES),studioAssetCategory)}</select>`)}${field('Artwork family',`<select id="studioAssetStyle">${Object.entries(MAP_PACKS).map(([id,p])=>`<option value="${id}" ${studioAssetStyle===id?'selected':''}>${esc(p.name||id)}</option>`).join('')}</select>`)}${field('Variation',`<select id="studioAssetVariant">${[0,1,2,3].map(v=>`<option value="${v}" ${studioAssetVariant===v?'selected':''}>${v+1}</option>`).join('')}</select>`)}</div><p class="studio-purpose">Placement adds an editable object to the current map. Imported images are saved with your project; kit slots let you reuse them across maps.</p></section><div id="studioAssetGrid">${studioAssetGrid()}</div>`;};
