document.addEventListener('change',e=>{const ids={studioAssetSource:v=>studioAssetSource=v,studioAssetCategory:v=>studioAssetCategory=v,studioAssetStyle:v=>studioAssetStyle=v,studioAssetVariant:v=>studioAssetVariant=+v};if(ids[e.target.id]){ids[e.target.id](e.target.value);studioAssetPage=0;render();}});
