function studioMapMediaIds(m){return [m.background,...m.objects.map(o=>o.assetId),...['kitSources','customSources','materialSources'].flatMap(k=>Object.values(m[k]||{})),...Object.values(m.furniturePlacement||{}).map(p=>p.assetId)].filter(Boolean);}
const completeMapDataBase=mapData;mapData=function(m){const result=completeMapDataBase(m),ids=new Set(studioMapMediaIds(m));result.assets=world.assets.filter(a=>ids.has(a.id)).map(a=>clone(a));return result;};
captureRecipe=function(name,entryId,writing=true,map=false){if(!world.entries.some(e=>e.id===entryId))throw Error('Choose a starting entry first.');const ids=new Set([entryId]);for(const r of [...world.relations,...world.familyLinks])if(r.from===entryId||r.to===entryId){ids.add(r.from);ids.add(r.to);}const maps=map&&currentMap()?[clone(currentMap())]:[];for(const m of maps)for(const o of m.objects)if(o.entryId)ids.add(o.entryId);const entries=clone(world.entries.filter(e=>ids.has(e.id))),documents=writing?clone(world.documents.filter(d=>d.links.some(id=>ids.has(id)))):[],worldKits=clone(world.worldKits.filter(k=>maps.some(m=>m.worldKitId===k.id))),imageIds=new Set([...entries.flatMap(e=>e.references),...maps.flatMap(studioMapMediaIds),...worldKits.flatMap(k=>['kitSources','customSources','materialSources'].flatMap(key=>Object.values(k[key]||{})).concat(Object.values(k.furniturePlacement||{}).map(p=>p.assetId)))]),soundIds=new Set([...entries.flatMap(e=>e.soundIds||[]),...maps.flatMap(m=>[...(m.soundIds||[]),...m.objects.flatMap(o=>o.soundIds||[])]),...worldKits.flatMap(k=>k.audioIds||[])]),emblems=clone(world.emblems.filter(e=>worldKits.some(k=>(k.emblemIds||[]).includes(e.id))||ids.has(e.entryId)));for(const e of emblems)if(e.assetId)imageIds.add(e.assetId);return {format:'jago-world-recipe',version:1,id:uid(),name,entries,documents,maps,relations:clone(world.relations.filter(r=>ids.has(r.from)&&ids.has(r.to))),familyLinks:clone(world.familyLinks.filter(r=>ids.has(r.from)&&ids.has(r.to))),worldKits,emblems,assets:clone(world.assets.filter(a=>imageIds.has(a.id))),soundtracks:clone(world.soundtracks.filter(s=>soundIds.has(s.id)))};};
recipeCandidate=function(recipe){if(recipe?.format!=='jago-world-recipe'||recipe.version!==1||typeof recipe.name!=='string'||!recipe.name.trim()||recipe.name.length>150)throw Error('Choose a valid .jagorecipe collection.');const required=['entries','documents','maps','relations','assets'],optional=['familyLinks','worldKits','emblems','soundtracks'];for(const key of required)if(!Array.isArray(recipe[key]))throw Error('Collection is missing '+key);for(const key of optional)if(recipe[key]!==undefined&&!Array.isArray(recipe[key]))throw Error('Invalid collection '+key);const sections=[...required,...optional],w=snapshot(),ids=new Map(),seen=new Set();for(const key of sections){const max=['assets','soundtracks','worldKits','emblems'].includes(key)?100:key==='maps'?50:3000;if((recipe[key]||[]).length>max)throw Error('Collection has too many '+key);for(const item of recipe[key]||[]){if(!item||typeof item.id!=='string'||seen.has(item.id))throw Error('Collection identities are missing or repeated.');seen.add(item.id);ids.set(item.id,uid());if(key==='maps'){for(const o of item.objects||[])ids.set(o.id,uid());for(const g of item.groups||[])ids.set(g.id,uid());if(item.complexId&&!ids.has(item.complexId))ids.set(item.complexId,uid());}}}
 const remap=v=>typeof v==='string'?ids.get(v)||v:Array.isArray(v)?v.map(remap):v&&typeof v==='object'?Object.fromEntries(Object.entries(v).filter(([k])=>!['__proto__','constructor','prototype'].includes(k)).map(([k,x])=>[k,remap(x)])):v,imported=remap(recipe);for(const key of sections)w[key].push(...(imported[key]||[]));for(const e of imported.entries){e.folderId='';if(!types().includes(e.type)&&!w.customTypes.includes(e.type))w.customTypes.push(e.type);}for(const d of imported.documents)if(!w.documents.some(x=>x.id===d.parentId))d.parentId='';for(const m of imported.maps){if(!w.maps.some(x=>x.id===m.parentId)){m.parentId='';m.parentObjectId='';}if(m.worldKitId&&!w.worldKits.some(k=>k.id===m.worldKitId))m.worldKitId='';}upgradeWorld(w);validateProject(w);return {world:w,imported};};
// A consistency review links to the exact entry, map or media repair workflow.
const comprehensiveReviewBase=reviewWorldWorkshop;reviewWorldWorkshop=function(){const rows=comprehensiveReviewBase();for(const i of missingMedia())rows.push({text:i.owner+' · '+i.location+' has missing '+i.type,media:true});const familyState=[familyRoot,familyMode,familySearch,studioFamilyDirection,worldYear];familyRoot='';familyMode='all';familySearch='';studioFamilyDirection='connected';worldYear=null;let cycles;try{cycles=familyLayout().cycles;}finally{[familyRoot,familyMode,familySearch,studioFamilyDirection,worldYear]=familyState;}for(const r of cycles)rows.push({text:r.name+' participates in circular ancestry or succession.',id:r.id});for(const d of world.documents){const unknown=[...d.body.matchAll(/\[\[([^\]]+)\]\]/g)].map(m=>m[1]).filter(name=>!world.entries.some(e=>e.name.toLowerCase()===name.toLowerCase()));if(unknown.length)rows.push({text:d.name+' references entries that do not exist: '+[...new Set(unknown)].join(', '),docId:d.id});}return rows;};
openWorkshopReview=function(){const rows=reviewWorldWorkshop();modal('World consistency review',`<p>Check references, dates, media and family cycles. These checks help you find issues; they do not judge your story.</p><p class="studio-review-count">${rows.length?rows.length+' things to inspect':'Nothing to report. References, dates and linked media passed the checks.'}</p>${!rows.length?`<p>${world.entries.length} entries · ${world.maps.length} maps · ${world.documents.length} documents checked.</p>`:''}${rows.map(f=>`<section class="mini-card"><p>${esc(f.text)}</p>${f.id?btn('Open entry','studio-review-entry',`data-id="${f.id}"`):f.mapId?btn('Open map','studio-review-map',`data-id="${f.mapId}"`):f.docId?btn('Open writing','studio-review-doc',`data-id="${f.docId}"`):f.media?btn('Repair media','studio-media-health'):''}</section>`).join('')}`,btn('Done','close-dialog'));};
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]'),a=b?.dataset.action;if(a?.startsWith('studio-review-')){$('#dialog').close();if(a==='studio-review-entry'){selectedEntry=b.dataset.id;navigate('entries');}if(a==='studio-review-map'){selectedMap=b.dataset.id;navigate('maps');}if(a==='studio-review-doc'){selectedDoc=b.dataset.id;navigate('writing');}}});
