const GENRE_SCENARIOS={fantasy:['A border crossing','Keeper of the old pact','The Lantern Wardens','A forgotten agreement is about to expire.','What price keeps the crossing safe?'],scifi:['The relay outpost','A stranded surveyor','The Transit Authority','A lost transmission contradicts the official survey.','Who controls access to the next jump?'],steampunk:['The floating dock','A boiler engineer','The Brassworkers’ Union','A failing engine exposes a dangerous labour bargain.','Who pays for the fuel and who breathes the smoke?'],horror:['The shuttered house','A returning witness','The Quiet Society','A familiar place contains evidence of an impossible visitor.','Which account can the witness trust?'],historical:['The river market','A travelling recorder','The Merchant Council','A disputed charter changes an ordinary household’s future.','Whose account survives in the records?'],contemporary:['The neighbourhood café','A new arrival','The Residents’ Association','A small public decision reveals a private obligation.','What does belonging cost here?'],postapoc:['The water station','A salvage runner','The Reservoir Compact','A vital supply route stops answering.','What can be repaired without repeating the old harm?'],cyberpunk:['The transit exchange','An identity broker','The Civic Network','A revoked identity locks someone out of their own life.','Who owns a person’s public record?'],cozy:['The village bakery','A new apprentice','The Seasonal Circle','A misplaced keepsake interrupts preparations for a festival.','Who needs a little help before the celebration?'],mythic:['The first sanctuary','Keeper of the turning year','The Children of the Dawn','A ritual fails and two origin stories disagree.','Which promise begins the next cycle?']};
function studioScenarioDialog(){const key=world.genreKey||'fantasy',s=GENRE_SCENARIOS[key]||GENRE_SCENARIOS.fantasy;modal('A connected '+(GENRES[key]?.name||world.genre)+' beginning',`<p>Add three linked draft entries, a scene and an open question. Existing work stays. Every name and prompt can be edited afterwards.</p><div class="fields">${field('Place',`<input id="studioScenarioPlace" value="${esc(s[0])}" maxlength="300">`)}${field('Person',`<input id="studioScenarioPerson" value="${esc(s[1])}" maxlength="300">`)}${field('Group',`<input id="studioScenarioGroup" value="${esc(s[2])}" maxlength="300">`)}${field('Opening situation',`<textarea id="studioScenarioSituation">${esc(s[3])}</textarea>`)}${field('Open question',`<textarea id="studioScenarioQuestion">${esc(s[4])}</textarea>`)}</div>`,btn('Create connected beginning','studio-scenario-create','','accent'));}
function studioCreateScenario(values){const names=[values.place,values.person,values.group].map(requireName);if(new Set(names.map(n=>n.toLowerCase())).size<3||names.some(n=>world.entries.some(e=>e.name.toLowerCase()===n.toLowerCase())))throw Error('Give each entry a distinct name that is not already in your world.');const [place,person,group]=names.map((n,i)=>newEntry(['Place','Character','Faction'][i],n)),situation=String(values.situation||'').slice(0,200000),question=String(values.question||'').slice(0,1000);place.summary=situation;person.summary='Their choices connect them to '+place.name+'.';group.summary='An organisation with a stake in '+place.name+'.';person.body='At [['+place.name+']], [['+group.name+']] offers a choice.\n\n'+situation;world.entries.push(place,person,group);world.relations.push({id:uid(),from:person.id,to:place.id,label:'Connected to',fromYear:null,toYear:null},{id:uid(),from:group.id,to:place.id,label:'Has a stake in',fromYear:null,toYear:null});const now=world.timeAnchor,d={id:uid(),name:'Arrival at '+place.name,body:situation+'\n\n[['+person.name+']] meets [['+group.name+']] at [['+place.name+']].',links:[place.id,person.id,group.id],order:world.documents.length,kind:'Scene',goal:question,conflict:'',status:'Draft',created:Date.now(),updated:Date.now()};world.documents.push(d);upgradeWorld(world);Object.assign(d.sceneContext,{locationId:place.id,povId:person.id,year:now.year,month:now.month,day:now.day});if(question)world.questions.push({id:uid(),text:question,answer:'',entryId:place.id,priority:'Normal',status:'Open'});world.storyContext.sceneId=d.id;world.storyContext.placeId=place.id;selectedDoc=d.id;view='writing';return {place,person,group,document:d};}
const completeGenreWorkbenchBase=genreWorkbench;genreWorkbench=function(){return `<section class="card"><h2>Start with a connected situation</h2><p>Give your genre a playable or writable beginning: a place, a person, a group and something that changes.</p>${btn('Preview connected beginning','studio-scenario','','accent')}</section>`+completeGenreWorkbenchBase();};
const completeNextDeskBase=nextDesk;nextDesk=function(){let html=completeNextDeskBase();if(nextDeskTab==='inbox'){html=html.replace(/<section class="card"><h3>Revisit an idea<\/h3>[\s\S]*?<\/section>/,'');for(const i of world.inbox)html=html.replace(`data-action="next-inbox-remove" data-id="${i.id}"`, `data-action="next-inbox-remove" data-id="${i.id}"`);html=html.replace(/(<button[^>]*data-action="next-inbox-remove"[^>]*data-id="([^"]+)"[^>]*>)/g,(_,button,id)=>btn('Edit','studio-idea-edit',`data-id="${id}"`)+button);}return html;};
document.addEventListener('click',e=>{const a=e.target.closest('[data-action]')?.dataset.action;if(a==='studio-scenario')studioScenarioDialog();if(a==='studio-scenario-create')try{const values={place:$('#studioScenarioPlace').value,person:$('#studioScenarioPerson').value,group:$('#studioScenarioGroup').value,situation:$('#studioScenarioSituation').value,question:$('#studioScenarioQuestion').value};let result;/* Validate the complete draft before adding any part. */const original=world,prior=studioContext();world=snapshot();try{result=studioCreateScenario(values);validateProject(world);}finally{world=original;view=prior.view;selectedEntry=prior.selectedEntry;selectedDoc=prior.selectedDoc;selectedMap=prior.selectedMap;}mutate(()=>studioCreateScenario(values));$('#dialog').close();toast('Connected entries and a scene created.');}catch(err){toast(err.message);}});
Object.assign(window.JagoWorld,{genreWorkbench,nextDesk,studioScenarioDialog,studioCreateScenario});
const assemblyUpgradeBase=upgradeWorld;upgradeWorld=function(w){assemblyUpgradeBase(w);w.mapAssemblies??=[];return w;};
function studioCaptureAssembly(m,objects,name){name=requireName(name).slice(0,100);if(!objects.length||objects.length>200)throw Error('Select between 1 and 200 objects to save an assembly.');const b=boundsFor(objects),members=new Set(objects.map(o=>o.id)),parts=clone(objects);for(const o of parts){relocateObject(o,clone(o),-b.x,-b.y);o.autoGenerated=false;o.locked=false;delete o.entryId;delete o.groupId;for(const key of ['linkFrom','linkTo'])if(o[key]&&!members.has(o[key]))delete o[key];}return {id:uid(),name,width:b.w,height:b.h,objects:parts};}
function studioPlaceAssembly(m,a,cx=m.width/2,cy=m.height/2){if(m.objects.length+a.objects.length>5000)throw Error('This map would exceed 5,000 objects.');const ids=new Map(a.objects.map(o=>[o.id,uid()])),parts=clone(a.objects);for(const o of parts){o.id=ids.get(o.id);for(const key of ['linkFrom','linkTo'])if(o[key])o[key]=ids.get(o[key])||'';relocateObject(o,clone(o),cx-a.width/2,cy-a.height/2);o.autoGenerated=false;delete o.groupId;}m.objects.push(...parts);makeMapGroup(m,a.name,parts,'assembly');mapMulti=new Set(parts.map(o=>o.id));mapSelection=parts[0]?.id;mapInspectorTab='arrange';mapInteractionMode='edit';mapTool='select';return parts;}
function studioAssemblyDialog(){const m=currentMap();if(!m)return toast('Create or open a map first.');modal('Reusable map assemblies',`<p>Keep a furnished room, courtyard, camp cluster or other selected arrangement. Geometry, colours and artwork stay editable. Lore links are cleared so a reused assembly can describe a new place.</p><p>${chosenObjects(m).length} selected objects</p>${field('New assembly name','<input id="studioAssemblyName" maxlength="100" placeholder="Workshop with sword racks">')}${btn('Save selected objects','studio-assembly-save')}<section><h3>Saved in this world</h3>${(world.mapAssemblies||[]).map(a=>`<div class="mini-card row"><strong>${esc(a.name)}</strong><small>${a.objects.length} objects</small>${btn('Place at view centre','studio-assembly-place',`data-id="${a.id}"`)}${btn('Remove','studio-assembly-delete',`data-id="${a.id}"`)}</div>`).join('')||'<p>No assemblies yet. Select several objects or an existing group, then save them here.</p>'}</section>`,btn('Done','close-dialog'));}
const assemblyEnhanceBase=enhanceMapView;enhanceMapView=function(){assemblyEnhanceBase();if(view==='maps'&&mapInteractionMode==='edit'&&mapInspectorTab==='arrange')$('#mapInspector')?.insertAdjacentHTML('beforeend',`<details class="carto-detail"><summary>Reusable assemblies</summary><p>Save rooms or groups of ordinary objects, then place editable copies.</p>${btn('Save / place assemblies','studio-assemblies')}</details>`);};
const assemblyValidationBase=validateProject;validateProject=function(w){const result=assemblyValidationBase(w);if(!Array.isArray(w.mapAssemblies)||w.mapAssemblies.length>50)throw Error('Keep up to 50 map assemblies.');const ids=new Set();for(const a of w.mapAssemblies){if(!a||typeof a.id!=='string'||ids.has(a.id)||typeof a.name!=='string'||!a.name.trim()||a.name.length>100||!Number.isFinite(a.width)||!Number.isFinite(a.height)||a.width<0||a.height<0||!Array.isArray(a.objects)||!a.objects.length||a.objects.length>200)throw Error('Invalid map assembly.');ids.add(a.id);const temp={...w,maps:[{...makeMap('Assembly validation','parchment'),width:8192,height:8192,objects:clone(a.objects),groups:[]}],mapAssemblies:[]};upgradeWorld(temp);assemblyValidationBase(temp);}return result;};
const assemblyMediaBase=missingMedia;missingMedia=function(w=world){const rows=assemblyMediaBase(w),ids=new Set(w.assets.map(a=>a.id));for(const a of w.mapAssemblies||[])for(const o of a.objects)if(o.assetId&&!ids.has(o.assetId))rows.push({type:'art',id:o.assetId,owner:a.name,location:'Saved assembly'});return rows;};
const assemblyReplaceBase=replaceMediaReferences;replaceMediaReferences=function(oldId,newId,type,w=world){assemblyReplaceBase(oldId,newId,type,w);if(type==='art')for(const a of w.mapAssemblies||[])for(const o of a.objects)if(o.assetId===oldId)o.assetId=newId||'';};
const assemblyPublicBase=publicWorld;publicWorld=function(...args){const result=assemblyPublicBase(...args);result.mapAssemblies=[];return result;};
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]'),a=b?.dataset.action;try{if(a==='studio-assemblies')studioAssemblyDialog();if(a==='studio-assembly-save'){const assembly=studioCaptureAssembly(currentMap(),chosenObjects(currentMap()),$('#studioAssemblyName').value);if((world.mapAssemblies||[]).length>=50)throw Error('This world already has 50 assemblies.');mutate(()=>world.mapAssemblies.push(assembly));studioAssemblyDialog();}if(a==='studio-assembly-place'){const assembly=world.mapAssemblies.find(a=>a.id===b.dataset.id),m=currentMap(),v=mapViewport;mutate(()=>studioPlaceAssembly(m,assembly,v?v.x+v.w/2:m.width/2,v?v.y+v.h/2:m.height/2));$('#dialog').close();}if(a==='studio-assembly-delete'){const id=b.dataset.id;confirmDelete('Remove this saved assembly?',()=>world.mapAssemblies=world.mapAssemblies.filter(a=>a.id!==id));}}catch(err){toast(err.message);}});
