const portablePresetControlsBase=presetControls;presetControls=function(kind){return portablePresetControlsBase(kind).replace('</section>',`<div class="row">${btn('Export selected','studio-preset-export',`data-kind="${kind}"`)}${btn('Import preset','studio-preset-import',`data-kind="${kind}"`)}</div></section>`);};
function studioImportPreset(raw,kind){if(raw?.format!=='jago-personal-preset'||raw.version!==1||raw.preset?.kind!==kind)throw Error('Choose a '+kind+' preset exported by Jago.');const p={id:uid(),name:String(raw.preset.name||''),kind,data:clone(raw.preset.data)},candidate=snapshot();candidate.personalPresets.push(p);validateProject(candidate);return p;}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]'),a=b?.dataset.action;if(a==='studio-preset-export')try{const p=personalPresets(b.dataset.kind).find(p=>p.id===$(`[data-personal-select="${b.dataset.kind}"]`).value);if(!p)throw Error('Choose a saved preset first.');download(slug(p.name)+'.jagopreset',JSON.stringify({format:'jago-personal-preset',version:1,preset:p},null,2),'application/json');}catch(err){toast(err.message);}if(a==='studio-preset-import'){const kind=b.dataset.kind,input=document.createElement('input');input.type='file';input.accept='.jagopreset,application/json';input.onchange=async()=>{try{const f=input.files[0];if(!f||f.size>60000)throw Error('Choose a preset file under 60 KB.');const p=studioImportPreset(JSON.parse(await f.text()),kind);mutate(()=>world.personalPresets.push(p));const select=$(`[data-personal-select="${kind}"]`);if(select){select.innerHTML=itemOptions(personalPresets(kind),p.id,'Choose your preset…');$(`[data-personal-name="${kind}"]`).value=p.name;}toast('Preset imported. Load it when ready.');}catch(err){toast(err.message);}};input.click();}});
exportDialog=function(){modal('Save & share',`<section class="card"><h3>Keep working</h3><p>An editable project includes private notes, maps, imported artwork, sounds, presets and saved kits. Local recovery helps with interruptions; keep a project file as your own backup.</p><div class="actions">${btn('Save editable project','save','','accent')}${btn('Named milestones / restore','studio-export-versions')}</div></section><section class="card"><h3>Share a reference</h3><div class="fields"><label class="check"><input type="checkbox" id="includeSecrets">Include private notes and events</label><label class="check"><input type="checkbox" id="canonOnly">Canon entries only</label></div><div class="actions">${btn('Readable HTML / print','export-bible','data-format="html"')}${btn('Markdown world bible','export-bible','data-format="md"')}${btn('Reference bundle · ZIP','export-bundle')}${btn('Structured world data · JSON','export-data')}</div><p class="studio-purpose">Public export hides dedicated secrets and private events. Ordinary prose stays, so review it before sharing.</p></section><section class="card"><h3>Designed presentations</h3><p>Choose a layout and preview the result before exporting.</p><div class="actions">${btn('Story chronicle','workshop-share-timeline')}${btn('Connection atlas','workshop-share-connections')}${btn('Building floor atlas','workshop-floor-atlas')}${btn('Current map · image / data / VTT','export-map')}</div></section>`,btn('Done','close-dialog'));};
