let studioJourneyStops=[];
function studioJourneyStopsHTML(){return `<ol class="studio-stage-list">${studioJourneyStops.map((id,i)=>`<li><span>${i+1}. ${esc(entry(id)?.name||'Missing place')}</span>${btn('↑','studio-stop-move',`data-index="${i}" data-step="-1" aria-label="Move stop up"`)}${btn('↓','studio-stop-move',`data-index="${i}" data-step="1" aria-label="Move stop down"`)}${btn('×','studio-stop-remove',`data-index="${i}" aria-label="Remove stop"`)}</li>`).join('')||'<li>No stops yet. Choose an entry and add it below.</li>'}</ol>`;}
function studioUpdateStops(){const host=$('#studioJourneyStops');if(host)host.innerHTML=studioJourneyStopsHTML();const source=$('#nextJourneyPlaces');if(source)source.value=studioJourneyStops.map(id=>entry(id)?.name||'').join('\n');}
const journeyFillBase=fillJourney;fillJourney=function(j){journeyFillBase(j);studioJourneyStops=[...j.places];studioUpdateStops();};
const journeyRenderBase=render;render=function(){journeyRenderBase();if(view==='nextworkshop'&&nextDeskTab==='journeys'&&$('#nextJourneyPlaces')){const source=$('#nextJourneyPlaces');studioJourneyStops=source.value.split('\n').map(n=>world.entries.find(e=>e.name===n)?.id).filter(Boolean);source.parentElement.hidden=true;source.parentElement.insertAdjacentHTML('afterend',`<section class="studio-journey-picker"><h3>Places in order</h3><div id="studioJourneyStops">${studioJourneyStopsHTML()}</div><div class="row">${roomSelect('studioJourneyPlace',world.entries.filter(e=>['Place','Location'].includes(e.type)),'','Choose a place')}${btn('Add stop','studio-stop-add')}</div><details><summary>Use another world entry as a stop</summary>${roomSelect('studioJourneyAny',world.entries,'','Choose an entry')}${btn('Add entry','studio-stop-add-any')}</details></section>`);}};
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]'),a=b?.dataset.action;if(a?.startsWith('studio-stop-')){const i=+b.dataset.index;if(a==='studio-stop-add'||a==='studio-stop-add-any'){const id=$(a.endsWith('any')?'#studioJourneyAny':'#studioJourneyPlace').value;if(id)studioJourneyStops.push(id);}if(a==='studio-stop-remove')studioJourneyStops.splice(i,1);if(a==='studio-stop-move'){const to=clamp(i+(+b.dataset.step),0,studioJourneyStops.length-1),[id]=studioJourneyStops.splice(i,1);studioJourneyStops.splice(to,0,id);}studioUpdateStops();}if(a==='next-journey-save'&&$('#studioJourneyStops')){e.preventDefault();e.stopImmediatePropagation();try{const textStops=$('#nextJourneyPlaces').value.trim(),pickedNames=studioJourneyStops.map(id=>entry(id)?.name||'').join('\n');if(textStops!==pickedNames){studioJourneyStops=textStops.split('\n').map(name=>{const matches=world.entries.filter(e=>e.name.toLowerCase()===name.trim().toLowerCase());if(matches.length!==1)throw Error('Choose a stop from the picker when names are missing or ambiguous.');return matches[0].id;});}if(!studioJourneyStops.length||studioJourneyStops.some(id=>!entry(id)))throw Error('Add existing world entries as journey stops.');const pace=+$('#nextJourneyPace').value,distance=$('#nextJourneyDistance').value===''?0:+$('#nextJourneyDistance').value;if(!Number.isFinite(pace)||pace<=0||!Number.isFinite(distance)||distance<0)throw Error('Use a positive travel pace and a distance of zero or more.');const j={id:editingJourney||uid(),name:requireName($('#nextJourneyName').value),transport:$('#nextJourneyTransport').value,places:[...studioJourneyStops],pace,distance,notes:$('#nextJourneyNotes').value};mutate(()=>{const i=world.journeys.findIndex(x=>x.id===j.id);if(i>=0)world.journeys[i]=j;else world.journeys.push(j);});editingJourney='';toast('Journey saved with '+j.places.length+' stops.');}catch(err){toast(err.message);}}},true);
