const familyOverrideValidationBase=validateProject;validateProject=function(w){const result=familyOverrideValidationBase(w);for(const m of w.maps)for(const o of m.objects)if(o.artworkFamily!==undefined&&!MAP_PACKS[o.artworkFamily])throw Error('Unknown artwork family.');return result;};
