addStarterAudio=function(id){const a=JAGO_STARTER_AUDIO.find(a=>a.id===id);if(!a)throw Error('Choose a starter sound.');const existing=world.soundtracks.find(t=>t.starterId===id);if(existing)return existing.id;if(world.soundtracks.reduce((n,t)=>n+t.bytes,0)+a.bytes>32*1048576)throw Error('Your audio pool is full.');const track={id:uid(),starterId:id,name:a.name,src:a.src,bytes:a.bytes,mime:a.mime,credit:a.credit,license:a.license,sourceURL:a.url,kind:a.kind,repeat:['Music','Ambience'].includes(a.kind)};mutate(()=>world.soundtracks.push(track));return track.id;};
playSound=function(id,reset=true){const a=world.soundtracks.find(a=>a.id===id);if(!a)return;starterPreview.pause();if(reset){audioQueue=a.repeat?[id]:[];audioIndex=0;}audioTrack=id;worldAudio.loop=false;worldAudio.src=a.src;worldAudio.play().catch(()=>toast('This audio file could not be played. Try MP3 or WAV.'));refreshAudioBar();};
const usefulSoundRoomBase=roomSound;roomSound=function(){let html=usefulSoundRoomBase();for(const a of world.soundtracks){const play=btn('Play','live-sound-play',`data-id="${a.id}"`);html=html.replace(play,play+`<label class="check"><input type="checkbox" data-studio-sound-repeat="${a.id}" ${a.repeat?'checked':''}>Repeat this track</label>`);if(a.starterId&&JAGO_STARTER_AUDIO.some(s=>s.id===a.starterId&&s.src!==a.src))html=html.replace(`<strong>${esc(a.name)}</strong>`,`<strong>${esc(a.name)}</strong>${btn('Use updated starter','studio-sound-update',`data-id="${a.id}"`)}`);}return html.replace('Optional free music and sound effects.','Music and ambience repeat when enabled. One-shot cues play once. The walking starter is an eight-second repeating sequence.').replace('Playlists loop in order.','Playlists loop in order; single-track repeat applies when playing from the pool.');};
document.addEventListener('change',e=>{if(e.target.dataset.studioSoundRepeat){const a=world.soundtracks.find(a=>a.id===e.target.dataset.studioSoundRepeat),repeat=e.target.checked;mutate(()=>a.repeat=repeat);if(audioTrack===a.id&&audioQueue.length<=1)audioQueue=repeat?[a.id]:[];}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-action="studio-sound-update"]');if(!b)return;const a=world.soundtracks.find(a=>a.id===b.dataset.id),s=JAGO_STARTER_AUDIO.find(s=>s.id===a.starterId);if(!s)return;const total=world.soundtracks.reduce((n,t)=>n+t.bytes,0)-a.bytes+s.bytes;if(total>32*1048576)return toast('Free some space in the audio pool first.');mutate(()=>Object.assign(a,{src:s.src,bytes:s.bytes,mime:s.mime,name:s.name,kind:s.kind,repeat:['Music','Ambience'].includes(s.kind)}));toast('Starter updated; its attachments and playlists are kept.');});
