const completeNameWorkshopBase=openNameWorkshop;openNameWorkshop=function(){completeNameWorkshopBase();$('#dialogBody').insertAdjacentHTML('beforeend',`<details class="card"><summary>Manage saved cultures & favourites</summary><h3>Culture rules</h3>${Object.keys(world.nameRules).map(name=>`<div class="row"><strong>${esc(name)}</strong>${btn('Edit','studio-culture-edit',`data-name="${esc(name)}"`)}${btn('Remove','studio-culture-remove',`data-name="${esc(name)}"`)}</div>`).join('')||'<p>No custom rules yet. Save one from Your own naming rules above.</p>'}<h3>Favourite names</h3>${world.nameFavourites.map((n,i)=>`<div class="row"><strong>${esc(n.name)}</strong><small>${esc(NAME_KINDS[n.kind]||n.kind)}</small>${btn('Use name…','studio-favourite-use',`data-index="${i}"`)}${btn('Remove','studio-favourite-remove',`data-index="${i}"`)}</div>`).join('')||'<p>Favourite a generated name to keep it here.</p>'}</details>`);};
function studioCultureDialog(name){const rule=world.nameRules[name];if(!rule)return;modal('Edit naming culture',`${field('Name',`<input id="studioCultureName" value="${esc(name)}" maxlength="100">`)}<div class="fields">${['Culture','Kind','Starts','Ends','Prefix','Suffix'].map(key=>field(key==='Culture'?'Base culture':key==='Kind'?'Name for':key==='Starts'?'Beginnings · comma separated':key==='Ends'?'Endings · comma separated':key,key==='Culture'?`<select id="studioCulture${key}">${Object.entries(NAME_CULTURES).map(([id,c])=>`<option value="${id}" ${rule[key]===id?'selected':''}>${esc(c.name)}</option>`).join('')}</select>`:key==='Kind'?`<select id="studioCulture${key}">${Object.entries(NAME_KINDS).map(([id,n])=>`<option value="${id}" ${rule[key]===id?'selected':''}>${esc(n)}</option>`).join('')}</select>`:`<input id="studioCulture${key}" value="${esc(rule[key]||'')}" maxlength="2000">`)).join('')}</div><p>Rules affect future names. Existing entries and favourites keep their names.</p>`,btn('Save culture','studio-culture-save',`data-name="${esc(name)}"`,'accent'));}
const isolatedEmblemSVGBase=emblemSVG;emblemSVG=function(e){const clip='herald-'+Math.floor(rng(JSON.stringify([e.shape]))()*1e9);return isolatedEmblemSVGBase(e).replaceAll('id="herald"',`id="${clip}"`).replaceAll('url(#herald)',`url(#${clip})`);};
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]'),a=b?.dataset.action;try{if(a==='studio-culture-edit')studioCultureDialog(b.dataset.name);if(a==='studio-culture-save'){const old=b.dataset.name,name=requireName($('#studioCultureName').value);if(name.length>100||['__proto__','constructor','prototype'].includes(name))throw Error('Choose a culture title under 100 characters.');if(name!==old&&Object.hasOwn(world.nameRules,name))throw Error('A culture already uses that name.');const rule=Object.fromEntries(['Culture','Kind','Starts','Ends','Prefix','Suffix'].map(key=>[key,$('#studioCulture'+key).value]));mutate(()=>{delete world.nameRules[old];world.nameRules[name]=rule;});openNameWorkshop();}if(a==='studio-culture-remove'){const name=b.dataset.name;confirmDelete('Remove naming culture '+name+'?',()=>delete world.nameRules[name]);}if(a==='studio-favourite-remove'){const i=+b.dataset.index;mutate(()=>world.nameFavourites.splice(i,1));openNameWorkshop();}if(a==='studio-favourite-use'){const n=world.nameFavourites[+b.dataset.index];workshopNames=[clone(n)];renderWorkshopNames();$('#workshopNames').scrollIntoView({block:'center'});}}catch(err){toast(err.message);}});
