const completeAsterExampleBase=makeExampleWorld;makeExampleWorld=function(){const w=completeAsterExampleBase();upgradeWorld(w);for(const r of w.relations.filter(r=>r.kind==='parent'))if(!w.familyLinks.some(f=>f.from===r.from&&f.to===r.to&&f.role==='parent'))w.familyLinks.push({id:uid(),from:r.from,to:r.to,role:'parent',since:r.since??null,until:r.until??null,notes:r.label});const guide=w.documents.find(d=>/Start Here/.test(d.name));if(guide)guide.body+='\n\n## Studio workflows\nWorld kit is the home for visual kits, names, emblems and sound. Assets browses the built-in families alongside imported artwork. Family & succession includes Hana and Akio’s established parent relationship. Save a selected map group as an assembly from Layers & selection, or export a personal preset to reuse it in another world. Story room’s focus mode keeps the scene and its references nearby. The Save & share dialog separates editable backups from designed presentations.';return w;};
const completeSpaceExampleBase=makeSpaceExampleWorld;
