const studioWorkflowHelpBase=help;help=function(){studioWorkflowHelpBase();$('#dialogBody').insertAdjacentHTML('beforeend','<details open><summary>Everyday studio workflows</summary><p>The sidebar groups Create, Explore, Develop, Resources and Project tools. Back returns to the previous workspace; linked writing has its own Back to writing action that restores the caret.</p><p>World kit gathers kit creation, cultures, emblems and sound. Assets includes built-in families and imported images. A placed built-in symbol retains its selected artwork family; change it in the selection inspector.</p><p>Save groups or furnished rooms as reusable assemblies in Layers & selection. Place copies, then edit their geometry, materials and lore. Assemblies and personal presets are saved with the world; presets can also be exported as .jagopreset files.</p><p>Journey stops use an ordered entry picker. Family & succession offers ancestor and descendant views, search highlighting and a fit control. In Story room, Focus on the story hides setup controls.</p><p>Save & share separates editable projects and milestones from references and designed exports. Consistency review shows a positive result when there are no findings and gives direct actions for affected entries, writing, maps or media.</p><p>Sound desk distinguishes repeating music/ambience from one-shot cues. Walking is an eight-second rhythmic starter. Older imported starter copies can be updated without losing their attachments.</p></details>');};
Object.assign(window.JagoWorld,{enhanceMapView,undo,redo,help});
const STUDIO_NATURAL_SYMBOLS=new Set(['forest','mountain','pine','oak','palm','dead-tree','jungle','flower','cactus','rock','coastal-rocks','hill','dune','reef','swamp','vineyard']);
mapChecks=function(m){const issues=[],symbols=m.objects.filter(o=>o.kind==='symbol'&&objectVisible(o,m)&&activeAt(o,mapYear??worldYear)),labels=labelBoxes(m),cell=Math.max(24,...symbols.map(o=>o.size||1)),bins=new Map();const binKey=(x,y)=>Math.floor(x/cell)+':'+Math.floor(y/cell);symbols.forEach((o,i)=>{const key=binKey(o.x,o.y);if(!bins.has(key))bins.set(key,[]);bins.get(key).push(i);});for(let i=0;i<symbols.length;i++){const a=symbols[i],gx=Math.floor(a.x/cell),gy=Math.floor(a.y/cell),candidates=[];for(let dx=-1;dx<=1;dx++)for(let dy=-1;dy<=1;dy++)candidates.push(...(bins.get((gx+dx)+':'+(gy+dy))||[]));for(const j of candidates.sort((a,b)=>a-b)){if(j<=i)continue;const b=symbols[j];if(!m.checkNaturalOverlaps&&STUDIO_NATURAL_SYMBOLS.has(a.symbol)&&STUDIO_NATURAL_SYMBOLS.has(b.symbol))continue;if(Math.hypot(a.x-b.x,a.y-b.y)<(a.size+b.size)*.5)issues.push({kind:'Overlap',text:`${a.label||SYMBOLS[a.symbol]?.name||'A symbol'} overlaps ${b.label||SYMBOLS[b.symbol]?.name||'another symbol'}.`,ids:[a.id,b.id]});}if(['world','region'].includes(m.kind)&&['town','capital'].includes(a.symbol)){const lands=m.coastMode==='edited'?m.objects.filter(o=>o.coastEditable).map(o=>o.points):m.terrain?.lands||[];if(lands.length&&!lands.some(p=>pointInPolygon(a.x,a.y,p)))issues.push({kind:'Location',text:`${a.label||'A settlement'} is outside the land shapes.`,ids:[a.id]});}}
for(let i=0;i<labels.length;i++)for(let j=i+1;j<labels.length;j++){const a=labels[i],b=labels[j];if(Math.min(a.x+a.w,b.x+b.w)>Math.max(a.x,b.x)&&Math.min(a.y+a.h,b.y+b.h)>Math.max(a.y,b.y))issues.push({kind:'Labels',text:'Two labels may collide. Arrange labels can try alternate positions.',ids:[a.id,b.id]});}for(const o of m.objects){if(!objectVisible(o,m)||!activeAt(o,mapYear??worldYear))continue;if(o.x!==undefined&&(o.x<0||o.y<0||o.x>m.width||o.y>m.height))issues.push({kind:'Crop',text:`${o.label||o.kind} is partly outside the map canvas.`,ids:[o.id]});if(o.kind==='river'&&m.grid){const g=m.grid,heights=o.points.map(p=>{const x=clamp(Math.floor(p[0]/m.width*g.cols),0,g.cols-1),y=clamp(Math.floor(p[1]/m.height*g.rows),0,g.rows-1);return g.filled?.[y*g.cols+x]??g.height[y*g.cols+x];});if(heights.some((h,i)=>i&&h>heights[i-1]+.08))issues.push({kind:'Drainage',text:'A drawn river appears to climb the elevation grid. Reverse its direction or edit the path if that was unintentional.',ids:[o.id]});}}return issues.slice(0,80);};
const usefulMapChecksDialogBase=mapChecksDialog;mapChecksDialog=function(){usefulMapChecksDialogBase();$('#dialogBody .notice')?.insertAdjacentHTML('afterend',`<label class="check"><input id="studioCheckNaturalOverlaps" type="checkbox" ${currentMap().checkNaturalOverlaps?'checked':''}>Also flag overlapping trees, mountains and natural detail</label><p class="studio-purpose">Natural clusters are allowed by default. Checks use nearby symbols and approximate label bounds; inspect a finding before changing your artwork.</p>`);};
document.addEventListener('change',e=>{if(e.target.id==='studioCheckNaturalOverlaps'){const checked=e.target.checked;mutate(()=>currentMap().checkNaturalOverlaps=checked);mapChecksDialog();}});
Object.assign(window.JagoWorld,{mapChecks,mapChecksDialog});
