const isolatedKitSampleBase=kitSample;kitSample=function(k){let art=isolatedKitSampleBase(k),prefix='kit-preview-'+(k.id||'draft')+'-',ids=[...art.matchAll(/\bid="([^"]+)"/g)].map(m=>m[1]);for(const id of new Set(ids))art=art.replaceAll('id="'+id+'"','id="'+prefix+id+'"').replaceAll('url(#'+id+')','url(#'+prefix+id+')').replaceAll('href="#'+id+'"','href="#'+prefix+id+'"');return art;};
Object.assign(window.JagoWorld,{kitSample});



// Release writing assistance: prose spelling, without changing names or saved content.
(()=>{let enabled=localStorage.getItem('jago-world-spelling')!=='off';function apply(root=document){for(const el of root.querySelectorAll('textarea,input[type=text],input:not([type]),[contenteditable=true]')){if(/seed|colour|color|url|search|file|path/i.test(el.id+' '+el.name))continue;el.spellcheck=enabled;el.lang='en-GB'}}const observer=new MutationObserver(records=>{if(records.some(r=>r.addedNodes.length))apply()});observer.observe(document.body,{childList:true,subtree:true});apply();setTimeout(()=>{const menu=document.querySelector('.suite-resource-menu');if(!menu)return;const b=document.createElement('button');const label=()=>{b.textContent='Writing spellcheck: '+(enabled?'on':'off');b.setAttribute('aria-pressed',enabled)};b.onclick=()=>{enabled=!enabled;localStorage.setItem('jago-world-spelling',enabled?'on':'off');apply();label()};label();menu.append(b)},1300);})();
